func compileBenchmarkEvidenceSchema(t *testing.T) *jsonschema.Schema {
	t.Helper()

	repoRoot := benchRepoRoot(t)
	rawSchema, err := os.ReadFile(filepath.Join(repoRoot, "scripts", "benchmark", "benchmark-evidence.schema.json"))
	if err != nil {
		t.Fatalf("read benchmark evidence schema: %v", err)
	}

	compiler := jsonschema.NewCompiler()
	compiler.AssertFormat = true
	if err := compiler.AddResource("benchmark-evidence.schema.json", bytes.NewReader(rawSchema)); err != nil {
		t.Fatalf("add benchmark evidence schema: %v", err)
	}
	schema, err := compiler.Compile("benchmark-evidence.schema.json")
	if err != nil {
		t.Fatalf("compile benchmark evidence schema: %v", err)
	}
	return schema
}

func loadBenchmarkEvidenceFixture(t *testing.T, name string) map[string]any {
	t.Helper()

	repoRoot := benchRepoRoot(t)
	raw, err := os.ReadFile(filepath.Join(repoRoot, "cmd", "bench", "testdata", "benchmark-evidence", name))
	if err != nil {
		t.Fatalf("read fixture %s: %v", name, err)
	}

	dec := json.NewDecoder(bytes.NewReader(raw))
	dec.UseNumber()
	var doc map[string]any
	if err := dec.Decode(&doc); err != nil {
		t.Fatalf("parse fixture %s: %v", name, err)
	}
	return doc
}

func assertString(t *testing.T, doc map[string]any, path, want string) {
	t.Helper()
	got, ok := lookupPath(doc, path)
	if !ok {
		t.Fatalf("missing %s", path)
	}
	str, ok := got.(string)
	if !ok {
		t.Fatalf("%s = %T, want string", path, got)
	}
	if str != want {
		t.Fatalf("%s = %q, want %q", path, str, want)
	}
}

func assertBool(t *testing.T, doc map[string]any, path string, want bool) {
	t.Helper()
	got, ok := lookupPath(doc, path)
	if !ok {
		t.Fatalf("missing %s", path)
	}
	b, ok := got.(bool)
	if !ok {
		t.Fatalf("%s = %T, want bool", path, got)
	}
	if b != want {
		t.Fatalf("%s = %t, want %t", path, b, want)
	}
}

func lookupPath(doc map[string]any, path string) (any, bool) {
	var cur any = doc
	for _, segment := range bytes.Split([]byte(path), []byte(".")) {
		m, ok := cur.(map[string]any)
		if !ok {
			return nil, false
		}
		next, ok := m[string(segment)]
		if !ok {
			return nil, false
		}
		cur = next
	}
	return cur, true
}

// Command bench discovers (harness, provider, model) candidates from
// agent config and runs a corpus of small tasks to produce per-task metrics.
package main

import (
	"flag"
	"fmt"
	"os"

	"github.com/DocumentDrivenDX/fizeau/internal/productinfo"
)

func main() {
	os.Exit(run(os.Args[1:]))
}

func run(args []string) int {
	if len(args) == 0 {
		printUsage()
		return 2
	}

	switch args[0] {
	case "discover":
		return cmdDiscover(args[1:])
	case "run":
		return cmdRun(args[1:])
	case "report":
		return cmdReport(args[1:])
	case "profiles":
		return cmdProfiles(args[1:])
	case "evidence":
		return cmdEvidence(args[1:])
	case "matrix":
		return cmdMatrix(args[1:])
	case "matrix-aggregate":
		return cmdMatrixAggregate(args[1:])
	case "help", "-h", "--help":
		printUsage()
		return 0
	default:
		fmt.Fprintf(os.Stderr, "%s: unknown command %q\n", benchCommandName(), args[0])
		printUsage()
		return 2
	}
}

func benchCommandName() string {
	return productinfo.BinaryName + "-bench"
}

func printUsage() {
	fmt.Fprintf(os.Stderr, `Usage: %s <command> [flags]

Commands:
  discover   List discovered (harness, provider, model) candidates
  run        Run corpus against discovered candidates
  report     Render a results file as table, json, or markdown
  profiles   Manage v7 benchmark profiles (subcommand: list)
  evidence   Validate and append benchmark evidence records
  matrix     Run the SD-010 harness/profile/task matrix
  matrix-aggregate
             Aggregate matrix cell reports into matrix.json, matrix.md, costs.json

Run '%s <command> -h' for command-specific flags.
`, benchCommandName(), benchCommandName())
}

// resolveWorkDir returns the working directory: --work-dir flag or cwd.
func resolveWorkDir(wd string) string {
	if wd != "" {
		return wd
	}
	d, err := os.Getwd()
	if err != nil {
		return "."
	}
	return d
}

// flagSet creates a FlagSet that writes to stderr with ContinueOnError.
func flagSet(name string) *flag.FlagSet {
	fs := flag.NewFlagSet(name, flag.ContinueOnError)
	fs.SetOutput(os.Stderr)
	return fs
}

package main

import (
	"path/filepath"
	"time"

	fizeau "github.com/DocumentDrivenDX/fizeau"
	agentConfig "github.com/DocumentDrivenDX/fizeau/internal/config"
)

// configAdapter wraps *config.Config and satisfies fizeau.ServiceConfig.
type configAdapter struct {
	cfg     *agentConfig.Config
	workDir string
}

var _ fizeau.ServiceConfig = (*configAdapter)(nil)

func (a *configAdapter) ProviderNames() []string { return a.cfg.ProviderNames() }

func (a *configAdapter) DefaultProviderName() string { return a.cfg.DefaultName() }

func (a *configAdapter) Provider(name string) (fizeau.ServiceProviderEntry, bool) {
	pc, ok := a.cfg.GetProvider(name)
	if !ok {
		return fizeau.ServiceProviderEntry{}, false
	}
	endpoints := make([]fizeau.ServiceProviderEndpoint, 0, len(pc.Endpoints))
	for _, endpoint := range pc.Endpoints {
		endpoints = append(endpoints, fizeau.ServiceProviderEndpoint{
			Name:    endpoint.Name,
			BaseURL: endpoint.BaseURL,
		})
	}
	return fizeau.ServiceProviderEntry{
		Type:      pc.Type,
		BaseURL:   pc.BaseURL,
		Endpoints: endpoints,
		APIKey:    pc.APIKey,
		Model:     pc.Model,
	}, true
}

func (a *configAdapter) HealthCooldown() time.Duration { return 0 }

func (a *configAdapter) WorkDir() string { return a.workDir }

func (a *configAdapter) SessionLogDir() string {
	if a.workDir == "" {
		return ""
	}
	return filepath.Join(a.workDir, agentConfig.ProjectConfigDirName(), "sessions")
}

